import{_ as s,o as a,c as e,a0 as t}from"./chunks/framework.DCluYYrN.js";const c=JSON.parse('{"title":"App Profile","description":"","frontmatter":{},"headers":[],"relativePath":"ja_JP/guide/app-profile.md","filePath":"ja_JP/guide/app-profile.md"}'),l={name:"ja_JP/guide/app-profile.md"};function o(p,i,h,n,d,r){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="app-profile" tabindex="-1">App Profile <a class="header-anchor" href="#app-profile" aria-label="Permalink to &quot;App Profile&quot;">​</a></h1><p>App Profile は KernelSU が提供する仕組みで、さまざまなアプリの設定を柔軟にカスタマイズできます。</p><p>root 権限（<code>su</code> を利用できること）を付与したアプリの場合、App Profile は Root Profile とも呼べます。<code>su</code> コマンドの <code>uid</code>、<code>gid</code>、<code>groups</code>、<code>capabilities</code>、<code>SELinux</code> ルールを調整できるため、root ユーザーの特権を細かく制限できます。たとえばファイアウォールアプリにだけネットワーク権限を与えてファイルアクセスを禁止したり、凍結アプリには完全な root の代わりに shell 権限のみを与えたりできます。<strong>すなわち最小権限の原則で力を箱の中に閉じ込める</strong>ことができます。</p><p>root 権限を持たない通常のアプリに対しても、App Profile は kernel やモジュールシステムがそのアプリをどのように扱うかを制御できます。モジュールによる変更をアプリで見せるべきかなどを決められ、設定に基づいて kernel／モジュールシステムは「隠す」といった挙動を選択できます。</p><h2 id="root-profile" tabindex="-1">Root Profile <a class="header-anchor" href="#root-profile" aria-label="Permalink to &quot;Root Profile&quot;">​</a></h2><h3 id="uid・gid・グループ" tabindex="-1">UID・GID・グループ <a class="header-anchor" href="#uid・gid・グループ" aria-label="Permalink to &quot;UID・GID・グループ&quot;">​</a></h3><p>Linux にはユーザーとグループの 2 つの概念があります。各ユーザーにはユーザー ID (UID) があり、ユーザーは複数のグループに所属できます。それぞれのグループにはグループ ID (GID) があり、これらの ID がシステム内でのユーザー識別やアクセス可能なリソースの判断に使われます。</p><p>UID が 0 のユーザーは root ユーザー、GID が 0 のグループは root グループと呼ばれます。root グループは一般的にシステムでもっとも強い権限を持ちます。</p><p>Android では各アプリ（shared UID を除く）が独立したユーザーとして動作し、固有の UID を持ちます。たとえば <code>0</code> は root、<code>1000</code> は <code>system</code>、<code>2000</code> は ADB shell、<code>10000</code>〜<code>19999</code> は一般アプリに割り当てられます。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>ここでいう UID は Android のマルチユーザーやワークプロファイルとは別の概念です。ワークプロファイルは UID の範囲を分割することで実装されています。たとえば 10000-19999 がメインユーザー、110000-119999 がワークプロファイルを表し、その中の各アプリは独自の UID を持っています。</p></div><p>各アプリは複数のグループに所属でき、GID はそのうちのプライマリグループを表します（多くの場合 UID と同じです）。その他のグループは補助グループです。ネットワークアクセスや Bluetooth など、いくつかの権限はグループで管理されています。</p><p>例として、ADB shell で <code>id</code> コマンドを実行すると次のような結果になります。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oriole:/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">id</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) gid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) groups</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1004</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1007</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1011</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1015</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdcard_rw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1028</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdcard_r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1078</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ext_data_rw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1079</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ext_obb_rw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net_bt_admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3002</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net_bt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3003</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3006</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net_bw_stats</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3009</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readproc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3011</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uhid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3012</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readtracefs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) context</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">u:r:shell:s0</span></span></code></pre></div><p>ここでは UID が <code>2000</code>、GID（プライマリグループ ID）も <code>2000</code> です。さらに <code>inet</code>（<code>AF_INET</code> や <code>AF_INET6</code> を作成できる、つまりネットワークアクセスが可能）、<code>sdcard_rw</code>（SD カードの読み書きが可能）といった補助グループにも所属しています。</p><p>KernelSU の Root Profile を使うと、<code>su</code> 実行後の root プロセスの UID・GID・所属グループをカスタマイズできます。たとえばある root アプリの Root Profile で UID を <code>2000</code> に設定すれば、そのアプリが <code>su</code> を使っても実際の権限は ADB shell 相当になります。またグループから <code>inet</code> を外せば、<code>su</code> コマンドがネットワークにアクセスできなくなります。</p><div class="tip custom-block"><p class="custom-block-title">注意</p><p>App Profile が制御するのは <code>su</code> 使用後の root プロセスの権限だけであり、アプリ自身の権限ではありません。アプリがネットワーク権限を要求して許可されていれば、<code>su</code> を使わなくてもネットワークにアクセスできます。<code>su</code> から <code>inet</code> グループを外すのは、<code>su</code> にネットワークアクセスをさせないためだけの措置です。</p></div><p>Root Profile は kernel によって強制され、<code>su</code> でユーザーやグループを切り替えるようなアプリ側の自発的な動作には依存しません。<code>su</code> 権限を与えるかどうかは開発者ではなくユーザー自身が完全にコントロールできます。</p><h3 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h3><p>Capability は Linux における特権分離の仕組みです。</p><p>従来の <code>UNIX</code> 実装では、権限チェックのためにプロセスを 2 種類に分けます。effective UID が <code>0</code> の特権プロセス（superuser/root）と、それ以外の非特権プロセスです。特権プロセスは kernel の権限チェックをすべてバイパスし、非特権プロセスはプロセスの資格情報（effective UID・effective GID・補助グループ一覧など）に基づいた完全なチェックを受けます。</p><p>Linux 2.2 以降は、従来 root が一括して持っていた権限を capability と呼ばれる単位に分割し、それぞれを独立して有効化・無効化できるようになりました。</p><p>各 capability は 1 つ以上の権限を表します。たとえば <code>CAP_DAC_READ_SEARCH</code> は、ファイル読み取りやディレクトリの読み取り・実行に必要なチェックをバイパスできる権限です。effective UID が <code>0</code> のユーザー（root）であっても、<code>CAP_DAC_READ_SEARCH</code> などを持っていなければ自由にファイルを読めません。</p><p>KernelSU の Root Profile では <code>su</code> 実行後の root プロセスの capability もカスタマイズでき、いわば「部分的な root 権限」を与えられます。上で触れた UID / GID と異なり、<code>su</code> 後も UID <code>0</code> が必要な root アプリもあります。その場合は UID <code>0</code> のまま capability を制限することで、許可される操作を限定できます。</p><div class="tip custom-block"><p class="custom-block-title">強く推奨</p><p>Linux の capability については<a href="https://man7.org/linux/man-pages/man7/capabilities.7.html" target="_blank" rel="noreferrer">公式ドキュメント</a>に詳細がまとまっています。capability をカスタマイズする予定があるなら、まずこのドキュメントを読んでください。</p></div><h3 id="selinux" tabindex="-1">SELinux <a class="header-anchor" href="#selinux" aria-label="Permalink to &quot;SELinux&quot;">​</a></h3><p>SELinux は強力な Mandatory Access Control (MAC) 仕組みで、<strong>default deny</strong>（明示的に許可されていない操作はすべて拒否）という原則で動作します。</p><p>SELinux には 2 つのグローバルモードがあります。</p><ol><li>Permissive モード: 拒否イベントを記録しますが強制しません。</li><li>Enforcing モード: 拒否イベントを記録し、かつ強制します。</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>近年の Android は SELinux に大きく依存してシステム全体の安全性を保っています。何のメリットもないので、「Permissive モード」で動作するカスタムシステムの利用は強く非推奨です。</p></div><p>SELinux の全容を説明するのは非常に複雑で、このドキュメントの範囲を超えています。まずは以下の資料で仕組みを理解することをおすすめします。</p><ol><li><a href="https://en.wikipedia.org/wiki/Security-Enhanced_Linux" target="_blank" rel="noreferrer">Wikipedia</a></li><li><a href="https://www.redhat.com/en/topics/linux/what-is-selinux" target="_blank" rel="noreferrer">Red Hat: What Is SELinux?</a></li><li><a href="https://wiki.archlinux.org/title/SELinux" target="_blank" rel="noreferrer">ArchLinux: SELinux</a></li></ol><p>KernelSU の Root Profile では、<code>su</code> 実行後の root プロセスの SELinux コンテキストもカスタマイズできます。特定のコンテキストに対してアクセス制御ルールを定義し、root 権限をきめ細かく制御できます。</p><p>一般的なシナリオでは、アプリが <code>su</code> を実行すると <code>u:r:ksu:s0</code> のような<strong>制限のない</strong> SELinux ドメインに切り替わります。Root Profile を介して <code>u:r:app1:s0</code> のようなカスタムドメインに切り替え、そのドメイン向けに次のようなルールを定義できます。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">enforce</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">typeattribute</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mlstrustedsubject</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span></span></code></pre></div><p><code>allow app1 * * *</code> というルールは例示目的であり、実際にはあまり使うべきではありません。Permissive モードとほとんど変わらなくなってしまうからです。</p><h3 id="エスカレーション" tabindex="-1">エスカレーション <a class="header-anchor" href="#エスカレーション" aria-label="Permalink to &quot;エスカレーション&quot;">​</a></h3><p>Root Profile の設定が適切でないと、意図せず制限を回避される恐れがあります。</p><p>たとえば ADB shell ユーザーに root 権限を与えていて（よくある構成です）、さらに通常アプリにも root 権限を付与したあと、そのアプリの Root Profile で UID 2000（ADB shell の UID）を設定したとします。この場合、アプリは <code>su</code> を 2 回実行するだけで完全な root を得られます。</p><ol><li>1 回目の <code>su</code> は App Profile の制限を受け、UID を <code>0</code> ではなく <code>2000</code>（ADB shell）に変更します。</li><li>2 回目の <code>su</code> は、既に UID が <code>2000</code> であり、その UID に root 権限を許可しているため、完全な root 権限を取得します。</li></ol><div class="tip custom-block"><p class="custom-block-title">ヒント</p><p>カスタムの<code>App Profile</code>で<code>NO_NEW_PRIVS</code>フラグを有効にすることができます。</p><p>これにより、プロセスが<code>su</code>コマンドを介して権限を昇格させることを防止できます。</p><p>ただし、このフラグはKernelSUによるプロセスの権限昇格を<strong>阻止する</strong>だけであり、他のLinuxメカニズムを使用して権限を昇格させることは可能です。</p><p>したがって、権限設定には十分注意してください。</p></div><h2 id="非-root-プロファイル" tabindex="-1">非 root プロファイル <a class="header-anchor" href="#非-root-プロファイル" aria-label="Permalink to &quot;非 root プロファイル&quot;">​</a></h2><h3 id="モジュールのアンマウント" tabindex="-1">モジュールのアンマウント <a class="header-anchor" href="#モジュールのアンマウント" aria-label="Permalink to &quot;モジュールのアンマウント&quot;">​</a></h3><p>KernelSU は OverlayFS をマウントすることで systemless な形でシステムパーティションを変更します。しかしこの挙動に敏感なアプリもあります。そのような場合は「Umount modules」オプションを設定して、対象アプリではモジュールをアンマウントさせることができます。</p><p>KernelSU マネージャーの設定画面には「Umount modules by default」という項目もあります。デフォルトではこのオプションは<strong>有効</strong>で、追加設定をしない限り KernelSU や一部モジュールはそのアプリでモジュールをアンマウントします。この挙動を望まない、あるいは一部アプリに影響する場合は、次のいずれかの方法を取ってください。</p><ol><li>「Umount modules by default」を有効のままにし、モジュールを読み込みたいアプリの App Profile では個別に「Umount modules」を無効にする（ホワイトリスト方式）。</li><li>「Umount modules by default」を無効にし、アンマウントしたいアプリでのみ個別に「Umount modules」を有効にする（ブラックリスト方式）。</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>カーネル 5.10 以降を実行しているデバイスでは、カーネルが追加の処理なしにモジュールをアンマウントします。一方 5.10 未満のデバイスでは、このオプションは設定値を示すだけで KernelSU は何もしません。5.10 より前のカーネルで「Umount modules」を使いたい場合は、<code>fs/namespace.c</code> にある <code>path_umount</code> 関数をバックポートする必要があります。詳細は <a href="https://kernelsu.org/guide/how-to-integrate-for-non-gki.html#how-to-backport-path_umount" target="_blank" rel="noreferrer">Integrate for non-GKI devices</a> ページの末尾を参照してください。Zygisksu など一部モジュールも、モジュールをアンマウントすべきかどうかを判断するためにこのオプションを参照します。</p></div>`,46)])])}const E=s(l,[["render",o]]);export{c as __pageData,E as default};
